import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"Sparks","description":"Sparks are self-contained behaviours that augment an element forged with UIX Forge.","frontmatter":{"title":"Sparks","description":"Sparks are self-contained behaviours that augment an element forged with UIX Forge."},"headers":[],"relativePath":"en/projects/uix/forge/sparks/index.md","filePath":"en/projects/uix/forge/sparks/index.md","lastUpdated":1793118610000}'),i={name:"en/projects/uix/forge/sparks/index.md"};function n(l,e,s,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<blockquote><p>Adapted from the canonical English UIX documentation by <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Source: <code>dev</code> / <strong>9.0.0-beta.2</strong>, revision <a href="https://github.com/Lint-Free-Technology/uix/commit/26e54e6d4973231a393933e6479ed1b03cc86cd3" target="_blank" rel="noreferrer">26e54e6</a>, reviewed 22 October 2026. This source mirror may describe preview behavior beyond stable 8.4.0. Markup adapted for this site; the <a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">original documentation</a> remains authoritative.</p></blockquote><h1 id="sparks" tabindex="-1">Sparks <a class="header-anchor" href="#sparks" aria-label="Permalink to &quot;Sparks&quot;">​</a></h1><p>Sparks are optional behaviours added to a <a href="./../">UIX Forge</a> forged element via the <code>forge.sparks</code> list. Each spark has a <code>type</code> key and its own configuration options.</p><p>Available sparks:</p><ul><li>💬 <a href="./tooltip">Tooltip</a> — attach a styled tooltip to any element within the forged element.</li><li>:material-button-cursor: <a href="./button">Button</a> — insert an interactive <code>ha-button</code> element as a sibling after any element within the forged element.</li><li>:material-badge-account-horizontal-outline: <a href="./badge">Badge</a> — insert a Web Awesome-styled <code>uix-badge</code> as a sibling before or after any element within the forged element.</li><li>🏷️ <a href="./attribute">Attribute</a> — add, replace or remove an attribute of any element within the forged element.</li><li>⚡ <a href="./event">Event</a> — receive DOM events from <code>fire-dom-event</code> actions and expose their data as template variables.</li><li>⭐ <a href="./tile-icon">Tile Icon</a> — insert a <code>ha-tile-icon</code> element as a sibling before or after any element within the forged element.</li><li>🛡️ <a href="./state-badge">State Badge</a> — insert a <code>state-badge</code> element as a sibling before or after any element within the forged element.</li><li>:material-grid: <a href="./grid">Grid</a> — apply CSS Grid layout to any container element within the forged element.</li><li>🔍 <a href="./search">Search</a> — find elements within a container by CSS selector and optional text filter, then apply class, attribute, or text mutations to all matches.</li><li>:material-map: <a href="./map">Map</a> — preserve the zoom level and centre of a map card across Home Assistant state updates.</li><li>:material-lock: <a href="./lock">Lock</a> — overlay a lock icon on any element to block interaction until the user passes a PIN, passphrase, or confirmation challenge.</li><li>:material-information-outline: <a href="./more-info">More-info</a> — embed Home Assistant more-info content for an entity inside a forged element.</li><li>:material-form-select: <a href="./form">Form</a> — add a Home Assistant form and optional submit and clear actions to a forged element.</li><li>:material-star-four-points-outline: <a href="./overlay-icon">Overlay Icon</a> — overlay a <code>ha-icon</code>/<code>ha-state-icon</code> on any element inside the forged element.</li><li>:material-image-outline: <a href="./background">Background</a> — inject a background layer (colour, image, video, or live camera) behind any element within the forged element.</li><li>:material-palette: <a href="./theme">Theme</a> — apply a Frontend theme to the forged element or one of its descendants.</li></ul>',5)])])}const p=a(i,[["render",n]]);export{f as __pageData,p as default};
